package com.getradejournal;

import com.google.inject.Provides;
import net.runelite.client.util.Filepath;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.GrandExchangeOfferChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@PluginDescriptor(name="GE Trade Journal", internalName="ge-trade-journal", description="Save Grand Exchange offers and fills as local JSON files", tags={"grand exchange","ge","history","trading"})
public class GeTradeJournalPlugin extends Plugin
{
    private static final Logger log=LoggerFactory.getLogger(GeTradeJournalPlugin.class);
    @Inject private Client client;
    @Inject private ItemManager items;
    @Inject private GeTradeJournalConfig config;
    private String character;
    private TradeJournal journal;
    private int ticksSinceLogin;
    private int ticksSinceSnapshot;
    private boolean trackingWasEnabled;

    @Provides GeTradeJournalConfig provideConfig(ConfigManager manager)
    { return manager.getConfig(GeTradeJournalConfig.class); }

    @Override protected void startUp()
    { character=null; journal=null; ticksSinceLogin=0; ticksSinceSnapshot=0; trackingWasEnabled=false; }

    @Override protected void shutDown()
    { character=null; journal=null; trackingWasEnabled=false; }

    @Subscribe public void onGameStateChanged(GameStateChanged e)
    {
        if (e.getGameState()==GameState.LOGGED_IN) { ticksSinceLogin=0; ticksSinceSnapshot=0; }
        else if (e.getGameState()!=GameState.LOGGED_IN) { journal=null; character=null; ticksSinceLogin=0; ticksSinceSnapshot=0; }
    }

    @Subscribe public void onGameTick(GameTick e)
    {
        if (!config.enabled())
        {
            // Resume with a new baseline instead of claiming fills that happened while disabled.
            trackingWasEnabled=false;
            journal=null;
            character=null;
            return;
        }
        if (client.getGameState()!=GameState.LOGGED_IN) return;
        if (!trackingWasEnabled)
        {
            journal=null;
            character=null;
            ticksSinceLogin=0;
            ticksSinceSnapshot=0;
            trackingWasEnabled=true;
        }
        if (!ensureCharacter()) return;
        ticksSinceLogin++;
        if (!journal.isBootstrapped() && ticksSinceLogin>=4)
        {
            GrandExchangeOffer[] current=client.getGrandExchangeOffers();
            if (current==null || current.length<8) return;
            OfferState[] state=new OfferState[8]; String[] names=new String[8];
            for(int i=0;i<8;i++)
            {
                state[i]=offer(i,current[i]);
                names[i]=itemName(state[i].itemId);
            }
            try { journal.bootstrap(state,names); }
            catch (Exception ex) { log.warn("GE Trade Journal baseline write failed",ex); }
        }
        if (journal.isBootstrapped() && ++ticksSinceSnapshot>=5)
        {
            ticksSinceSnapshot=0;
            // Client may update the offer state without firing an event in some transitions.
            GrandExchangeOffer[] current=client.getGrandExchangeOffers();
            if (current != null && current.length>=8)
            {
                for(int i=0;i<8;i++) report(i,current[i]);
            }
        }
    }

    @Subscribe public void onGrandExchangeOfferChanged(GrandExchangeOfferChanged e)
    {
        if (!config.enabled() || !trackingWasEnabled || client.getGameState()!=GameState.LOGGED_IN) return;
        if (!ensureCharacter() || journal==null || !journal.isBootstrapped()) return;
        report(e.getSlot(),e.getOffer());
    }

    private boolean ensureCharacter()
    {
        if (client.getLocalPlayer()==null || client.getLocalPlayer().getName()==null) return false;
        String name=client.getLocalPlayer().getName().trim();
        if (name.isEmpty()) return false;
        if (name.equals(character) && journal!=null) return true;
        String safe=name.replaceAll("[\\\\/:*?\"<>|]","_").replaceAll("[. ]+$","");
        if (safe.isEmpty()) return false;
        try
        {
            Filepath dir=getPluginDirectory().joinSegment(safe);
            dir.createDirectories();
            journal=new TradeJournal(new LocalJournal(dir),name);
            character=name;
            ticksSinceLogin=0;
            ticksSinceSnapshot=0;
            log.info("GE Trade Journal recording local files for {}",name);
            return true;
        }
        catch (Exception ex) { log.warn("GE Trade Journal cannot create local character folder",ex); return false; }
    }

    private OfferState offer(int slot,GrandExchangeOffer offer)
    {
        if(offer==null) return new OfferState(slot,0,0,0,0,0,"EMPTY");
        return new OfferState(slot,offer.getItemId(),offer.getPrice(),offer.getTotalQuantity(),
            offer.getQuantitySold(),offer.getSpent(),String.valueOf(offer.getState()));
    }

    private String itemName(int id)
    {
        if (id<=0) return "";
        try { return items.getItemComposition(id).getName(); }
        catch (RuntimeException ex) { return "Item "+id; }
    }

    private void report(int slot,GrandExchangeOffer ge)
    {
        if (journal==null || slot<0 || slot>7) return;
        OfferState state=offer(slot,ge);
        try { journal.observe(state,itemName(state.itemId)); }
        catch (Exception ex) { log.warn("GE Trade Journal event persistence failed (slot {})",slot,ex); }
    }
}

package com.getradejournal;

import java.io.IOException;

/** Storage boundary for append-only GE history and current snapshots. */
interface JournalStorage
{
    void append(String jsonLine) throws IOException;
    void current(String json) throws IOException;
}

package com.getradejournal;

final class JsonText
{
    private JsonText() {}

    static String q(String value)
    {
        if (value == null) return "null";
        StringBuilder sb = new StringBuilder("\"");
        for (int i = 0; i < value.length(); i++)
        {
            char c = value.charAt(i);
            switch (c)
            {
                case '\\': sb.append("\\\\"); break;
                case '"': sb.append("\\\""); break;
                case '\n': sb.append("\\n"); break;
                case '\r': sb.append("\\r"); break;
                case '\t': sb.append("\\t"); break;
                default:
                    if (c < 32) sb.append(String.format("\\u%04x", (int)c));
                    else sb.append(c);
            }
        }
        return sb.append('"').toString();
    }
}

package com.getradejournal;

import java.io.IOException;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.StandardCopyOption;
import java.nio.file.StandardOpenOption;
import net.runelite.client.util.Filepath;

/** Local-only, append-only history and crash-safe replacement of current snapshots. */
final class LocalJournal implements JournalStorage
{
    private final Filepath dir;

    LocalJournal(Filepath dir) throws IOException
    {
        this.dir = dir;
        dir.createDirectories();
    }

    @Override public void append(String jsonLine) throws IOException
    {
        dir.joinSegment("events.jsonl").write(jsonLine + "\n",
            StandardOpenOption.CREATE, StandardOpenOption.APPEND);
    }

    @Override public void current(String json) throws IOException
    {
        Filepath target = dir.joinSegment("current_offers.json");
        Filepath temp = dir.createTempFile("current_offers", ".tmp");
        try
        {
            temp.write(json);
            try
            {
                temp.moveTo(target, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
            }
            catch (AtomicMoveNotSupportedException ex)
            {
                temp.moveTo(target, StandardCopyOption.REPLACE_EXISTING);
            }
        }
        finally
        {
            temp.deleteIfExists();
        }
    }
}

package com.getradejournal;

/** An immutable, SDK-independent GE offer snapshot. */
final class OfferState
{
    final int slot;
    final int itemId;
    final long price;
    final int quantity;
    final int filled;
    final long cumulativeGp;
    final String status;
    final String side;

    OfferState(int slot, int itemId, long price, int quantity, int filled, long cumulativeGp, String status)
    {
        this.slot=slot; this.itemId=itemId; this.price=price;
        this.quantity=quantity; this.filled=filled; this.cumulativeGp=cumulativeGp;
        this.status=status == null ? "EMPTY" : status;
        String s=this.status.toUpperCase(java.util.Locale.ROOT);
        this.side = s.contains("BUY") || s.contains("BOUGHT") ? "BUY" :
            s.contains("SELL") || s.contains("SOLD") ? "SELL" : "UNKNOWN";
    }

    boolean isEmpty() { return itemId <= 0 || quantity <= 0 || "EMPTY".equalsIgnoreCase(status); }
    boolean isTerminal()
    {
        String s=status.toUpperCase(java.util.Locale.ROOT);
        return s.contains("CANCEL") || s.contains("ABORT") || s.contains("BOUGHT") || s.contains("SOLD");
    }
    boolean isComplete()
    {
        String s=status.toUpperCase(java.util.Locale.ROOT);
        return quantity > 0 && filled >= quantity && (s.contains("BOUGHT") || s.contains("SOLD"));
    }
    boolean isCancelled()
    {
        String s=status.toUpperCase(java.util.Locale.ROOT);
        return s.contains("CANCEL") || s.contains("ABORT");
    }
    boolean sameOrder(OfferState next)
    {
        return next != null && !isEmpty() && !next.isEmpty() &&
            itemId==next.itemId && side.equals(next.side) &&
            price==next.price && quantity==next.quantity &&
            next.filled >= filled && next.cumulativeGp >= cumulativeGp &&
            !(isTerminal() && !next.isTerminal());
    }
}

package com.getradejournal;

import java.io.IOException;
import java.time.Instant;
import java.util.HashMap;
import java.util.Map;
import java.util.UUID;

/** Pure-Java order tracking. Never posts data to a network endpoint. */
final class TradeJournal
{
    private final JournalStorage journal;
    private final String account;
    private final String sessionId=UUID.randomUUID().toString();
    private final Map<Integer, OfferState> offers=new HashMap<>();
    private final Map<Integer, String> orderIds=new HashMap<>();
    private final Map<Integer, String> names=new HashMap<>();
    private boolean bootstrapped=false;

    TradeJournal(JournalStorage journal, String account) { this.journal=journal; this.account=account; }
    boolean isBootstrapped() { return bootstrapped; }

    // Initial login is a baseline, not historical fill events.
    void bootstrap(OfferState[] initial, String[] itemNames) throws IOException
    {
        if (bootstrapped) return;
        for (int i=0; i<8; i++)
        {
            OfferState cur=initial != null && i < initial.length ? initial[i] : null;
            if (cur==null || cur.isEmpty()) continue;
            offers.put(i,cur);
            orderIds.put(i,UUID.randomUUID().toString());
            names.put(i,itemNames != null && i < itemNames.length ? itemNames[i] : "");
            append("OFFER_OBSERVED",cur,orderIds.get(i),0,0,"Existing offer at recording start; prior fills are not new",names.get(i));
        }
        bootstrapped=true;
        snapshot();
    }

    void observe(OfferState next,String itemName) throws IOException
    {
        if (!bootstrapped || next==null || next.slot<0 || next.slot>7) return;
        int slot=next.slot;
        OfferState prev=offers.get(slot);
        String orderId=orderIds.get(slot);
        if (next.isEmpty())
        {
            if (prev != null && !prev.isEmpty())
            {
                append("OFFER_CLEARED",prev,orderId,0,0,"Slot cleared; do not infer a cancellation or sale",names.get(slot));
            }
            offers.remove(slot); orderIds.remove(slot); names.remove(slot);
            snapshot(); return;
        }
        if (prev==null || prev.isEmpty() || !prev.sameOrder(next))
        {
            if (prev!=null && !prev.isEmpty() && !prev.isTerminal())
            {
                append("ORDER_REPLACED_OR_CHANGED",prev,orderId,0,0,
                    "Order identity changed; prior offer outcome may require review",names.get(slot));
            }
            orderId=UUID.randomUUID().toString();
            orderIds.put(slot,orderId);
            names.put(slot,itemName);
            offers.put(slot,next);
            // The first observation can already include partial fills; their exact delta is unknown.
            append(next.isTerminal() ? "OFFER_OBSERVED_TERMINAL" : "OFFER_STARTED",next,orderId,0,0,
                next.filled>0 ? "Already filled when first observed; historical delta unknown" : "",itemName);
        }
        else
        {
            int deltaQty=next.filled-prev.filled;
            long deltaGp=next.cumulativeGp-prev.cumulativeGp;
            if (deltaQty>0 && deltaGp>=0)
            {
                append(next.side.equals("BUY") ? "BUY_FILL" : next.side.equals("SELL") ? "SELL_FILL" : "UNKNOWN_FILL",
                    next,orderId,deltaQty,deltaGp,"",itemName);
            }
            else if (deltaQty>0 || deltaGp != 0)
            {
                append("REVIEW_REQUIRED",next,orderId,0,0,
                    "Inconsistent filled quantity or cumulative GP; never inferred a fill",itemName);
            }
            if (!prev.isComplete() && next.isComplete()) append("OFFER_COMPLETED",next,orderId,0,0,"",itemName);
            if (!prev.isCancelled() && next.isCancelled()) append("OFFER_CANCELLED",next,orderId,0,0,"",itemName);
            offers.put(slot,next); names.put(slot,itemName);
        }
        snapshot();
    }

    void snapshot() throws IOException
    {
        StringBuilder json=new StringBuilder("{\"schema_version\":1,\"observed_at\":")
            .append(JsonText.q(Instant.now().toString())).append(",\"account\":")
            .append(JsonText.q(account)).append(",\"session_id\":")
            .append(JsonText.q(sessionId)).append(",\"offers\":[");
        for(int slot=0;slot<8;slot++)
        {
            if(slot>0) json.append(',');
            OfferState offer=offers.get(slot);
            if(offer==null) json.append("{\"slot\":").append(slot).append(",\"empty\":true}");
            else json.append(payload(offer,orderIds.get(slot),names.get(slot))).append(",\"empty\":false}");
        }
        json.append("]}");
        journal.current(json.toString());
    }

    private String payload(OfferState offer,String orderId,String itemName)
    {
        return "{\"slot\":"+offer.slot+
            ",\"order_id\":"+JsonText.q(orderId)+
            ",\"item_id\":"+offer.itemId+
            ",\"item_name\":"+JsonText.q(itemName)+
            ",\"side\":"+JsonText.q(offer.side)+
            ",\"state\":"+JsonText.q(offer.status)+
            ",\"offer_price\":"+offer.price+
            ",\"total_quantity\":"+offer.quantity+
            ",\"filled_quantity\":"+offer.filled+
            ",\"cumulative_gp\":"+offer.cumulativeGp;
    }

    private void append(String type,OfferState offer,String orderId,int qty,long gp,String note,String itemName) throws IOException
    {
        String line="{\"schema_version\":1,\"event_id\":"+JsonText.q(UUID.randomUUID().toString())+
            ",\"time\":"+JsonText.q(Instant.now().toString())+
            ",\"event\":"+JsonText.q(type)+
            ",\"account\":"+JsonText.q(account)+
            ",\"session_id\":"+JsonText.q(sessionId)+
            ",\"delta_quantity\":"+qty+
            ",\"delta_gp\":"+gp+
            ",\"note\":"+JsonText.q(note)+
            ",\"offer\":"+payload(offer,orderId,itemName)+"}}";
        journal.append(line);
    }
}

